  const text = document.body.innerText;
  const metrics = {};
  const patterns = {
    FCP: /First Contentful Paint[\s\S]{0,80}?(\d[\d.,]*\s*s)/i,
    LCP: /Largest Contentful Paint[\s\S]{0,80}?(\d[\d.,]*\s*s)/i,
    TBT: /Total Blocking Time[\s\S]{0,80}?(\d[\d.,]*\s*m?s)/i,
    CLS: /Cumulative Layout Shift[\s\S]{0,80}?(\d[\d.,]*)/i,
    SI: /Speed Index[\s\S]{0,80}?(\d[\d.,]*\s*s)/i,
    TTI: /Time to Interactive[\s\S]{0,80}?(\d[\d.,]*\s*s)/i,
    INP: /Interaction to Next Paint[\s\S]{0,80}?(\d[\d.,]*\s*m?s|N\/A)/i
  };
  for (const [k, re] of Object.entries(patterns)) {
    const m = text.match(re);
    metrics[k] = m ? m[1] : null;
  }
  // Also grab headings near Performance
  const scoreEls = [...document.querySelectorAll('*')].filter(el => /^\d{2,3}$/.test((el.textContent||'').trim()) && el.children.length===0).slice(0,20).map(el => ({t: el.textContent.trim(), cls: el.className, parent: (el.parentElement&&el.parentElement.innerText||'').slice(0,80)}));
  return { metrics, scoreEls, len: text.length, snippet: text.slice(0, 4000) };
})()

