(() => {
  function lum(c) {
    const m = c.match(/rgba?\((\d+),\s*(\d+),\s*(\d+)/);
    if (!m) return null;
    const [r,g,b] = m.slice(1).map(n => {
      const s = Number(n)/255;
      return s <= 0.03928 ? s/12.92 : Math.pow((s+0.055)/1.055, 2.4);
    });
    return 0.2126*r + 0.7152*g + 0.0722*b;
  }
  function contrast(fg, bg) {
    const L1 = lum(fg), L2 = lum(bg);
    if (L1==null || L2==null) return null;
    const [hi, lo] = L1>L2 ? [L1,L2] : [L2,L1];
    return ((hi+0.05)/(lo+0.05)).toFixed(2);
  }
  const kicker = document.querySelector('.section-kicker');
  const h1 = document.querySelector('#hero-heading');
  const jn = document.querySelector('.journey-number');
  const ks = kicker ? getComputedStyle(kicker) : null;
  const hs = h1 ? getComputedStyle(h1) : null;
  const js = jn ? getComputedStyle(jn) : null;
  const kb = kicker ? getComputedStyle(kicker.closest('section') || kicker.parentElement) : null;
  const fonts = [...document.fonts].map(f => f.family + ' ' + f.status).slice(0, 12);
  const sheets = [...document.styleSheets].map(s => s.href).filter(Boolean);
  return {
    googleCss: sheets.some(h => h.includes('fonts.googleapis')),
    kickerColor: ks && ks.color,
    kickerBg: kb && kb.backgroundColor,
    kickerContrast: ks && kb && contrast(ks.color, kb.backgroundColor),
    h1Opacity: hs && hs.opacity,
    h1Font: hs && hs.fontFamily,
    journeyColor: js && js.color,
    woffLinks: [...document.querySelectorAll('link[rel=preload][as=font]')].map(l => l.href),
    cssLinks: [...document.querySelectorAll('link[rel=stylesheet]')].map(l => l.href),
  };
})()

(() => {
  function lumFromRgb(r,g,b) {
    const lin = n => { const s=n/255; return s<=0.03928?s/12.92:Math.pow((s+0.055)/1.055,2.4); };
    return 0.2126*lin(r)+0.7152*lin(g)+0.0722*lin(b);
  }
  function parse(c) {
    const m = c.match(/rgba?\((\d+),\s*(\d+),\s*(\d+)/);
    return m ? m.slice(1).map(Number) : null;
  }
  function effectiveBg(el) {
    let n = el;
    while (n && n !== document.documentElement) {
      const bg = getComputedStyle(n).backgroundColor;
      const p = parse(bg);
      const a = (bg.match(/rgba\(\d+,\s*\d+,\s*\d+,\s*([\d.]+)/) || [1,1])[1];
      if (p && Number(a) > 0.05 && !(p[0]===0&&p[1]===0&&p[2]===0&&Number(a)===0)) {
        if (bg !== 'rgba(0, 0, 0, 0)' && bg !== 'transparent') return p;
      }
      n = n.parentElement;
    }
    return parse(getComputedStyle(document.body).backgroundColor);
  }
  function contrast(el) {
    const fg = parse(getComputedStyle(el).color);
    const bg = effectiveBg(el);
    const L1 = lumFromRgb(...fg), L2 = lumFromRgb(...bg);
    const [hi,lo] = L1>L2?[L1,L2]:[L2,L1];
    return { fg: getComputedStyle(el).color, bg, ratio: ((hi+0.05)/(lo+0.05)).toFixed(2), text: el.textContent.trim().slice(0,40) };
  }
  return {
    kickers: [...document.querySelectorAll('.section-kicker')].slice(0,6).map(contrast),
    journey: [...document.querySelectorAll('.journey-number')].map(contrast),
    access: [...document.querySelectorAll('.access-label')].map(contrast),
    product: [...document.querySelectorAll('.product-source')].map(contrast),
    workflow: [...document.querySelectorAll('.workflow-home-list li > span')].map(contrast),
  };
})()
